fn load_spans_from_file(
    path: &Path,
) -> Result<(
    HashMap<String, HashMap<PathBuf, Vec<SpanRange>>>,
    HashMap<String, String>,
    HashMap<PathBuf, String>,
    bool,
)> {
    let file = File::open(path)?;
    let mut reader = BufReader::new(file);
    let mut line = String::new();
    let mut span_index: HashMap<String, HashMap<PathBuf, Vec<SpanRange>>> = HashMap::new();
    let mut symbol_kinds: HashMap<String, String> = HashMap::new();
    let mut normalized_sources: HashMap<PathBuf, String> = HashMap::new();
    let mut saw_done = false;

    while reader.read_line(&mut line)? > 0 {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            line.clear();
            continue;
        }
        let value: Value = match serde_json::from_str(trimmed) {
            Ok(value) => value,
            Err(_) => {
                line.clear();
                continue;
            }
        };
        if let Some(kind) = value.get("type").and_then(|v| v.as_str()) {
            if kind == "done" {
                saw_done = true;
            } else if kind == "source" {
                if let (Some(file), Some(src)) = (
                    value.get("file").and_then(|v| v.as_str()),
                    value.get("src").and_then(|v| v.as_str()),
                ) {
                    normalized_sources.insert(PathBuf::from(file), src.to_string());
                }
            }
            line.clear();
            continue;
        }
        let symbol_id = match value.get("symbol_id").and_then(|v| v.as_str()) {
            Some(value) => value,
            None => {
                line.clear();
                continue;
            }
        };
        let kind = value
            .get("kind")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown");
        let file = match value.get("file").and_then(|v| v.as_str()) {
            Some(value) => value,
            None => {
                line.clear();
                continue;
            }
        };
        let lo = value.get("lo").and_then(|v| v.as_u64()).unwrap_or(0);
        let hi = value.get("hi").and_then(|v| v.as_u64()).unwrap_or(0);

        symbol_kinds
            .entry(symbol_id.to_string())
            .or_insert_with(|| kind.to_string());
        span_index
            .entry(symbol_id.to_string())
            .or_default()
            .entry(PathBuf::from(file))
            .or_default()
            .push(SpanRange {
                lo: lo as usize,
                hi: hi as usize,
            });

        line.clear();
    }

    Ok((span_index, symbol_kinds, normalized_sources, saw_done))
}

use crate::core::rustc_session::SpanRange;
use anyhow::{anyhow, Result};

#[derive(Clone, Debug)]
pub struct SpanReplacement {
    pub span: SpanRange,
    pub replacement: String,
}

pub fn patch_file(src: &str, spans: &[SpanReplacement]) -> Result<String> {
    if spans.is_empty() {
        return Ok(src.to_string());
    }
    let mut sorted = spans.to_vec();
    sorted.sort_by(|a, b| b.span.lo.cmp(&a.span.lo));
    let src_bytes = src.as_bytes();
    let mut chunks: Vec<Vec<u8>> = Vec::with_capacity(sorted.len() * 2 + 1);
    let mut cursor = src_bytes.len();
    for span in &sorted {
        let lo = span.span.lo;
        let hi = span.span.hi;
        if lo > hi || hi > src_bytes.len() {
            return Err(anyhow!("invalid span {}..{}", lo, hi));
        }
        if hi > cursor {
            return Err(anyhow!("overlapping spans at {}", lo));
        }
        chunks.push(src_bytes[hi..cursor].to_vec());
        chunks.push(span.replacement.as_bytes().to_vec());
        cursor = lo;
    }
    chunks.push(src_bytes[0..cursor].to_vec());
    chunks.reverse();
    let total_len: usize = chunks.iter().map(|c| c.len()).sum();
    let mut out = Vec::with_capacity(total_len);
    for chunk in chunks {
        out.extend_from_slice(&chunk);
    }
    String::from_utf8(out).map_err(|e| anyhow!("utf8 error after patch: {e}"))
}

use anyhow::Result;
