    let delta_total = sum_counts_i64(&delta_error_types);
    let compile_ms = compile_started.elapsed().as_millis();

    let accept = delta_total == 0 && rename_applied;
    let decision_reason = if accept {
        "accepted"
    } else if !rename_applied {
